// ═══════════════════════════════════════════════════════════════════════════
// VIDEO BACKGROUND — Autoplay + Scroll-Driven Visual Effects
// Video plays naturally. GSAP scroll animations layer on top:
// zoom, darkening overlay, blur, and hero content parallax exit.
// ═══════════════════════════════════════════════════════════════════════════
function initVideoBackground() {
    const video = document.getElementById('heroVideo');
    if (!video) return;

    // Autoplay the video in background (loop for continuous visual)
    video.currentTime = 0;
    video.loop = true;
    const playPromise = video.play();
    if (playPromise !== undefined) {
        playPromise.catch(() => {
            // Autoplay blocked — fallback image is visible behind
        });
    }

    // ── GSAP Scroll-Driven Effects on the Hero ────────────────────────
    gsap.registerPlugin(ScrollTrigger);

    // 1. Video ZOOM: scale 1 → 1.2 as user scrolls through hero
