// ═══════════════════════════════════════════════════════════════════════════
// VIDEO BACKGROUND — Scroll-Driven Scrubbing
// Video currentTime is tied to scroll position for cinematic effect.
// As user scrolls through the hero, the video plays forward frame-by-frame.
// ═══════════════════════════════════════════════════════════════════════════
function initVideoBackground() {
    const video = document.getElementById('heroVideo');
    if (!video) return;

    // Don't autoplay — we control playback via scroll
    video.pause();
    video.currentTime = 0;

    // Preload video metadata to know duration
    const setupScrub = () => {
        const duration = video.duration;
        if (!duration || isNaN(duration)) return;

        // Scroll-driven video scrub: as user scrolls through hero,
        // video plays from 0 to full duration
        gsap.registerPlugin(ScrollTrigger);

        // Create a proxy object for GSAP to tween
        const scrubProxy = { time: 0 };

        gsap.to(scrubProxy, {
            time: duration,
            ease: 'none',
            scrollTrigger: {
                trigger: '.hero-section',
                start: 'top top',
                end: 'bottom top',
                scrub: 0.5,  // Smooth 0.5s lag for cinematic feel
                onUpdate: () => {
                    // Clamp to valid range
                    video.currentTime = Math.min(scrubProxy.time, duration - 0.01);
                }
            }
        });

        // Also scale the video slightly on scroll for zoom effect
        gsap.to('#heroVideo', {
            scale: 1.15,
            ease: 'none',
            scrollTrigger: {
                trigger: '.hero-section',
                start: 'top top',
                end: 'bottom top',
                scrub: true
            }
        });
    };

    // Wait for metadata, or run immediately if already loaded
    if (video.readyState >= 1) {
        setupScrub();
    } else {
        video.addEventListener('loadedmetadata', setupScrub, { once: true });
    }

    // Fallback: if video fails to load, just show the static image
    video.addEventListener('error', () => {
        video.style.display = 'none';
    });
}

