// ═══════════════════════════════════════════════════════════════════════════
// CINEMATIC VIDEO SCRUBBING
// Video currentTime is tied to the total document scroll.
// As user scrolls down, camera flies through the apartment.
// ═══════════════════════════════════════════════════════════════════════════
function initVideoBackground() {
    const video = document.getElementById('heroVideo');
    if (!video) return;

    // Don't autoplay — we control playback via scroll
    video.pause();
    video.currentTime = 0;

    // Preload video metadata to know duration
    const setupScrub = () => {
        const duration = video.duration;
        if (!duration || isNaN(duration)) return;

        gsap.registerPlugin(ScrollTrigger);

        // Scrub video across the ENTIRE page scroll
        const scrubProxy = { time: 0 };
        gsap.to(scrubProxy, {
            time: duration,
            ease: 'none',
            scrollTrigger: {
                trigger: document.body,
                start: 'top top',
                end: 'bottom bottom',
                scrub: 0.8, // Smooth 0.8s lag for cinematic heavy feel
                onUpdate: () => {
                    video.currentTime = Math.min(scrubProxy.time, duration - 0.05);
                }
            }
        });

        // Add a global blur overlay that activates when not in the hero section
        // This ensures text in catalog/bento is readable against the busy video background
        const blurOverlay = document.createElement('div');
        blurOverlay.className = 'video-blur-layer';
        document.getElementById('globalVideoContainer').appendChild(blurOverlay);

        gsap.to(blurOverlay, {
            backdropFilter: 'blur(16px)',
            webkitBackdropFilter: 'blur(16px)',
            opacity: 1,
            backgroundColor: 'rgba(3, 3, 5, 0.6)',
            ease: 'none',
            scrollTrigger: {
                trigger: '.features-section',
                start: 'top 80%',
                end: 'top 20%',
                scrub: true
            }
        });
    };

    if (video.readyState >= 1) {
        setupScrub();
    } else {
        video.addEventListener('loadedmetadata', setupScrub, { once: true });
    }

    video.addEventListener('error', () => {
        video.style.display = 'none';
    });
}

