    will-change: transform;
}
.btn:active {
    transform: scale(0.97);
}"""
content = re.sub(r'\.btn\s*\{.*?(?=\n\n|\n\.btn-primary)', btn_replacement, content, flags=re.DOTALL)

with open('styles.css', 'w') as f:
    f.write(content)
EOF
