// ═══════════════════════════════════════════════════════════════════════════
// CINEMATIC VIDEO SCRUBBING
// Video currentTime is tied to the total document scroll.
// As user scrolls down, camera flies through the apartment.
// ═══════════════════════════════════════════════════════════════════════════
async function initVideoBackground() {
    const video = document.getElementById('heroVideo');
    const fallback = document.querySelector('.video-fallback');
    if (!video) return;

    video.pause();

    // To ensure perfect frame-by-frame scrubbing on local development servers
    // (which often don't support HTTP Range requests), we fetch the MP4 as a Blob
    // and use it entirely from memory. This guarantees 0 lag.
    try {
        const videoUrl = video.querySelector('source').src;
        const response = await fetch(videoUrl);
        if (!response.ok) throw new Error('Video fetch failed');
        const arrayBuffer = await response.arrayBuffer();
        // Force the MIME type so the browser doesn't reject the blob
        // (Python http.server often gets MIME types wrong)
        const blob = new Blob([arrayBuffer], { type: 'video/mp4' });
        const blobUrl = URL.createObjectURL(blob);
        video.src = blobUrl;
    } catch (e) {
        console.warn('Falling back to normal video src', e);
        // If fetch fails, just use the normal source
        video.src = video.querySelector('source').src;
    }

    video.load();

    const setupScrub = () => {
        // Hide fallback image since video is ready
        if (fallback) fallback.style.opacity = '0';

        const duration = video.duration;
        if (!duration || isNaN(duration) || duration === Infinity) return;

        gsap.registerPlugin(ScrollTrigger);

        const scrubProxy = { time: 0 };
        gsap.to(scrubProxy, {
            time: duration,
            ease: 'none',
            scrollTrigger: {
                trigger: document.body,
                start: 'top top',
                end: 'bottom bottom',
                scrub: 0.8, // Smooth 0.8s lag for cinematic heavy feel
                onUpdate: () => {
                    video.currentTime = Math.min(scrubProxy.time, duration - 0.05);
                }
            }
        });

        // Add a global blur overlay
        const blurOverlay = document.createElement('div');
        blurOverlay.className = 'video-blur-layer';
        document.getElementById('globalVideoContainer').appendChild(blurOverlay);

        gsap.to(blurOverlay, {
            backdropFilter: 'blur(16px)',
            webkitBackdropFilter: 'blur(16px)',
            opacity: 1,
            backgroundColor: 'rgba(3, 3, 5, 0.6)',
            ease: 'none',
            scrollTrigger: {
                trigger: '.features-section',
                start: 'top 80%',
                end: 'top 20%',
                scrub: true
            }
        });
    };

    if (video.readyState >= 2) {
        setupScrub();
    } else {
        video.addEventListener('loadeddata', setupScrub, { once: true });
    }

    video.addEventListener('error', () => {
        video.style.display = 'none';
        if (fallback) fallback.style.opacity = '1';
    });
}

